// Generates the SQL recurrence test from the shared fixture so the database
// implementation and src/modules/tasks/lib/recurrence.ts are checked against
// identical vectors.
import { readFileSync, writeFileSync } from 'node:fs'

const cases = JSON.parse(readFileSync('supabase/tests/fixtures/recurrence-cases.json', 'utf8'))
const q = (s) => `'${String(s).replaceAll("'", "''")}'`
const lines = [
  '-- GENERATED by scripts/gen-recurrence-sql-test.mjs from supabase/tests/fixtures/recurrence-cases.json. Do not edit.',
  'begin;',
  `select plan(${cases.length + 4});`,
  ...cases.map(
    (c) =>
      `select is(public.recurrence_next_date(${q(JSON.stringify(c.rule))}::jsonb, ${q(c.anchor)}::date, ${q(c.after)}::date), ${
        c.expected === null ? 'null::date' : `${q(c.expected)}::date`
      }, ${q(c.name)});`,
  ),
  `select ok(public.is_valid_recurrence('{"freq":"weekly","weekdays":[1,5]}'), 'valid weekly rule accepted');`,
  `select ok(not public.is_valid_recurrence('{"freq":"hourly"}'), 'unknown frequency rejected');`,
  `select ok(not public.is_valid_recurrence('{"freq":"daily","weekdays":[1]}'), 'weekdays only allowed on weekly rules');`,
  `select ok(not public.is_valid_recurrence('{"freq":"weekly","interval":0}'), 'interval must be positive');`,
  'select * from finish();',
  'rollback;',
  '',
]
writeFileSync('supabase/tests/database/02_recurrence.test.sql', lines.join('\n'))
